package workflows_test

import (
	"bytes"
	"context"
	"os"
	"os/exec"
	"path/filepath"
	"sort"
	"strings"
	"testing"
	"time"
)

// CHAOS-11670: the merge queue runs the external auth corpus when a queue entry touches ci/auth_corpus_paths.txt (the
// floor) OR a repo package of the `go list -deps` closure of the auth route packages. The closure is checked in as
// ci/auth_corpus_closure.txt (one repo directory per row, generated by ci/auth_corpus_closure_gen.sh); these tests fail
// when it drifts from go list, and when a floor row matches no tracked file.

const (
	corpusClosureTable = "ci/auth_corpus_closure.txt"
	corpusClosureGen   = "ci/auth_corpus_closure_gen.sh"
	corpusModule       = "github.com/full-chaos/dev-health-ops"
)

// The roots ruled for CHAOS-11670 (acp): the go-api auth route packages, the apiservice top level, both binaries.
var corpusClosureRoots = []string{
	"./internal/api/session", "./internal/api/sso", "./internal/api/policy", "./internal/apiservice", "./cmd/dho", "./cmd/auth-service",
}

func corpusRun(t *testing.T, root, name string, args ...string) string {
	t.Helper()
	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Minute)
	defer cancel()
	cmd := exec.CommandContext(ctx, name, args...)
	cmd.Dir = root
	var stdout, stderr bytes.Buffer
	cmd.Stdout, cmd.Stderr = &stdout, &stderr
	if err := cmd.Run(); err != nil {
		t.Fatalf("%s %v: %v\n%s", name, args, err, stderr.String())
	}
	return stdout.String()
}

// corpusGoListClosure is the oracle: the repo packages (module path prefix cut) of `go list -deps` of the roots, and
// the directory of each embedded file of those packages (go:embed reaches into subdirectories).
func corpusGoListClosure(t *testing.T, root string) []string {
	t.Helper()
	tmpl := `{{if not .Standard}}{{with .Module}}{{if eq .Path "` + corpusModule + `"}}P {{$.ImportPath}}{{"\n"}}{{range $.EmbedFiles}}E {{$.ImportPath}}/{{.}}{{"\n"}}{{end}}{{end}}{{end}}{{end}}`
	args := append([]string{"list", "-deps", "-f", tmpl}, corpusClosureRoots...)
	var dirs []string
	for _, line := range strings.Split(corpusRun(t, root, "go", args...), "\n") {
		kind, path, ok := strings.Cut(strings.TrimSpace(line), " ")
		if !ok {
			continue
		}
		path = strings.TrimPrefix(path, corpusModule+"/")
		if kind == "E" {
			path = filepath.Dir(path)
		}
		dirs = append(dirs, path)
	}
	sort.Strings(dirs)
	out := dirs[:0]
	for i, d := range dirs {
		if i == 0 || d != dirs[i-1] {
			out = append(out, d)
		}
	}
	return out
}

func corpusClosureRows(text string) []string {
	var rows []string
	for _, line := range strings.Split(text, "\n") {
		if line != "" && !strings.HasPrefix(line, "#") {
			rows = append(rows, line)
		}
	}
	return rows
}

// corpusClosureDrift lists the rows only the table has ("stale") and the directories only go list has ("missing").
func corpusClosureDrift(table, golist []string) (stale, missing []string) {
	in := map[string]bool{}
	for _, d := range golist {
		in[d] = true
	}
	have := map[string]bool{}
	for _, r := range table {
		have[r] = true
		if !in[r] {
			stale = append(stale, r)
		}
	}
	for _, d := range golist {
		if !have[d] {
			missing = append(missing, d)
		}
	}
	return stale, missing
}

func TestAuthCorpusClosureTableMatchesGoList(t *testing.T) {
	root := authProofRoot(t)
	table := corpusClosureRows(readFile(t, filepath.Join(root, corpusClosureTable)))
	stale, missing := corpusClosureDrift(table, corpusGoListClosure(t, root))
	if len(stale) > 0 || len(missing) > 0 {
		t.Fatalf("%s drifted from `go list -deps` of the roots; run `bash %s > %s`\nstale rows: %v\nmissing rows: %v", corpusClosureTable, corpusClosureGen, corpusClosureTable, stale, missing)
	}
}

func TestAuthCorpusClosureTableIsWhatTheGeneratorPrints(t *testing.T) {
	root := authProofRoot(t)
	if got, want := corpusRun(t, root, "bash", corpusClosureGen), readFile(t, filepath.Join(root, corpusClosureTable)); got != want {
		t.Fatalf("`bash %s` prints something other than %s; regenerate it", corpusClosureGen, corpusClosureTable)
	}
}

func TestAuthCorpusClosureDriftCheckSeesBothDirections(t *testing.T) {
	golist := []string{"cmd/dho", "internal/api/session", "internal/auth/x"}
	if s, m := corpusClosureDrift([]string{"cmd/dho", "internal/api/session", "internal/auth/x"}, golist); len(s)+len(m) != 0 {
		t.Errorf("equal sets reported drift: %v %v", s, m)
	}
	if s, m := corpusClosureDrift([]string{"cmd/dho", "internal/api/session"}, golist); len(s) != 0 || len(m) != 1 || m[0] != "internal/auth/x" {
		t.Errorf("a package missing from the table: stale=%v missing=%v", s, m)
	}
	if s, m := corpusClosureDrift([]string{"cmd/dho", "internal/api/session", "internal/auth/x", "internal/gone"}, golist); len(m) != 0 || len(s) != 1 || s[0] != "internal/gone" {
		t.Errorf("a stale row: stale=%v missing=%v", s, m)
	}
}

func TestAuthCorpusClosureTableHasTheRootsAndTheNamedCandidates(t *testing.T) {
	root := authProofRoot(t)
	have := map[string]bool{}
	for _, r := range corpusClosureRows(readFile(t, filepath.Join(root, corpusClosureTable))) {
		have[r] = true
	}
	var want []string
	for _, r := range corpusClosureRoots {
		want = append(want, strings.TrimPrefix(r, "./"))
	}
	for _, c := range []string{"sessionissue", "usersowned", "authmail", "oauthprovider", "registerorg", "clientip", "ratelimit", "pyheaders", "standinkey", "audit"} {
		want = append(want, "internal/api/"+c)
	}
	want = append(want, "internal/mail/templates", "internal/pgmigrate/sql", "internal/pgmigrate/sql/down", "internal/chmigrate/sql")
	want = append(want, "internal/audit", "internal/platform/config", "internal/apiservice/acr", "internal/apiservice/admin", "internal/apiservice/customerpush")
	for _, w := range want {
		if !have[w] {
			t.Errorf("%s has no row for %s", corpusClosureTable, w)
		}
	}
}

// corpusDeadRows runs the script's own `case` matching (bash, no extglob, `=` flat-row rule) over files and returns the
// rows that match none of them.
func corpusDeadRows(t *testing.T, rows, files []string) []string {
	t.Helper()
	const prog = `
rows=(); files=()
while IFS= read -r -d '' x; do rows+=("$x"); done < "$1"
while IFS= read -r -d '' x; do files+=("$x"); done < "$2"
for glob in "${rows[@]}"; do
  flat=0; pat=$glob
  if [[ $glob == =* ]]; then flat=1; pat=${glob#=}; fi
  hit=0
  for file in "${files[@]}"; do
    # shellcheck disable=SC2254
    case "$file" in
      ${pat})
        if [ "$flat" = 1 ] && [ "${file%/*}" != "${pat%/*}" ]; then continue; fi
        hit=1; break ;;
    esac
  done
  [ "$hit" = 1 ] || printf '%s\0' "$glob"
done
`
	dir := t.TempDir()
	write := func(name string, items []string) string {
		p := filepath.Join(dir, name)
		if err := writeNUL(p, items); err != nil {
			t.Fatal(err)
		}
		return p
	}
	out := corpusRun(t, dir, "bash", "-c", prog, "bash", write("rows", rows), write("files", files))
	var dead []string
	for _, r := range strings.Split(out, "\x00") {
		if r != "" {
			dead = append(dead, r)
		}
	}
	return dead
}

func TestAuthCorpusPathsRowsMatchATrackedFile(t *testing.T) {
	root := authProofRoot(t)
	files := strings.Split(strings.TrimSuffix(corpusRun(t, root, "git", "-c", "core.quotePath=false", "ls-files", "-z"), "\x00"), "\x00")
	if dead := corpusDeadRows(t, corpusRows(t, root), files); len(dead) > 0 {
		t.Fatalf("rows of %s that match no `git ls-files` path: %q", corpusQueuePaths, dead)
	}
}

func TestAuthCorpusPathsFloorNamesTheClosureFiles(t *testing.T) {
	rows := corpusRows(t, authProofRoot(t))
	for _, want := range []string{corpusClosureTable, corpusClosureGen} {
		found := false
		for _, r := range rows {
			if r == want {
				found = true
			}
		}
		if !found {
			t.Errorf("%s has no row for %s: a change to it must run the corpus", corpusQueuePaths, want)
		}
	}
}

func TestAuthCorpusDeadRowCheckSeesEveryDeadForm(t *testing.T) {
	files := []string{"go.mod", "internal/auth/a.go", "internal/audit/b.go", "docker/x.Dockerfile", "-x"}
	live := []string{"go.mod", "internal/auth/*", "=internal/auth/*.go", "docker/*", "internal/audit/b.go"}
	dead := []string{".", "..", "./internal/auth/*", "/internal/auth/*", "internal//auth/*", "internal/auth", "internal/auth/*  # the auth tree",
		"\vgo.mod", "\fgo.mod", "\u00a0go.mod", "\ufeffgo.mod", "internal/{auth,audit}/*", "!(internal)/auth/*", "=internal/*.go", "go.mod/"}
	got := corpusDeadRows(t, append(append([]string{}, live...), dead...), files)
	sort.Strings(got)
	want := append([]string{}, dead...)
	sort.Strings(want)
	if strings.Join(got, "\x00") != strings.Join(want, "\x00") {
		t.Fatalf("dead rows = %q, want %q", got, want)
	}
}

func writeNUL(path string, items []string) error {
	var b bytes.Buffer
	for _, it := range items {
		b.WriteString(it)
		b.WriteByte(0)
	}
	return os.WriteFile(path, b.Bytes(), 0o644)
}

// The generator pins the C locale itself, before its first command: its sort, read and sed are byte-exact whatever
// the caller's locale.
func TestAuthCorpusClosureGeneratorPinsTheCLocale(t *testing.T) {
	raw, err := os.ReadFile(filepath.Join(authProofRoot(t), corpusClosureGen))
	if err != nil {
		t.Fatal(err)
	}
	for i, line := range strings.Split(string(raw), "\n") {
		trimmed := strings.TrimSpace(line)
		if trimmed == "export LC_ALL=C" {
			return
		}
		if trimmed == "" || strings.HasPrefix(trimmed, "#") || strings.HasPrefix(trimmed, "set -") {
			continue
		}
		t.Fatalf("line %d runs a command before `export LC_ALL=C`: %s", i+1, line)
	}
	t.Fatal(corpusClosureGen + " never runs `export LC_ALL=C`")
}

func TestAuthCorpusClosureGeneratorOutputIgnoresTheLocale(t *testing.T) {
	root := authProofRoot(t)
	run := func(locale string) string {
		cmd := exec.Command("bash", corpusClosureGen)
		cmd.Dir = root
		cmd.Env = append(os.Environ(), "LC_ALL="+locale)
		out, err := cmd.Output()
		if err != nil {
			t.Fatalf("LC_ALL=%s: %v", locale, err)
		}
		return string(out)
	}
	if c, u := run("C"), run("en_US.UTF-8"); c != u {
		t.Fatal("the generator prints a different table under en_US.UTF-8 than under C")
	}
}
